    CONSTRAINT ck_from_seq_uint64 CHECK (((from_seq >= (1)::numeric) AND (from_seq <= '18446744073709551615'::numeric))),
    CONSTRAINT ck_gap_range CHECK ((from_seq <= through_seq)),
    CONSTRAINT ck_through_seq_uint64 CHECK (((through_seq >= (1)::numeric) AND (through_seq <= '18446744073709551615'::numeric)))
);


--
