    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_latest_ingested_seq_uint64 CHECK (((latest_ingested_seq >= (0)::numeric) AND (latest_ingested_seq <= '18446744073709551615'::numeric))),
    CONSTRAINT ck_stream_frontiers CHECK ((verified_through_seq <= latest_ingested_seq)),
    CONSTRAINT ck_verified_through_seq_uint64 CHECK (((verified_through_seq >= (0)::numeric) AND (verified_through_seq <= '18446744073709551615'::numeric)))
);


