    CONSTRAINT ck_tags_group_owner CHECK ((((tag_group = 'Line'::text) AND (asset_id IS NULL)) OR ((tag_group = ANY (ARRAY['Infeed'::text, 'Sealer'::text, 'Outfeed'::text])) AND (asset_id IS NOT NULL)))),
