INSERT INTO public.alembic_version(version_num) VALUES ('0014_mixed_alarm_runtime');
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC, hmi_app;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM PUBLIC, hmi_app;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC, hmi_app;
GRANT SELECT ON TABLE public."alembic_version", public."assets", public."roles", public."sites", public."tag_definitions" TO hmi_app;
GRANT SELECT, INSERT ON TABLE public."alarm_actions", public."alarm_capture_decisions", public."alarm_outbox", public."alarm_receipts", public."alarm_rule_versions", public."auth_audit", public."command_request_audit", public."equipment_state_events", public."event_apply_errors", public."execution_plans", public."ingest_batches", public."ingest_conflicts", public."mes_management_audit", public."production_events", public."run_summary_conflicts", public."work_order_cancellations", public."work_order_execution_links", public."work_order_releases" TO hmi_app;
GRANT SELECT, INSERT, UPDATE ON TABLE public."alarm_capture_frontiers", public."alarm_channels", public."alarm_instances", public."auth_sessions", public."command_requests", public."event_inbox", public."execution_totals", public."production_executions", public."recipe_versions", public."run_reconciliations", public."source_streams", public."stream_progress", public."users", public."work_orders" TO hmi_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public."auth_login_challenges", public."line_execution_reservations", public."stream_gaps", public."user_roles" TO hmi_app;
GRANT SELECT, UPDATE(id) ON TABLE public.lines TO hmi_app;
GRANT USAGE, SELECT ON SEQUENCE public."alarm_actions_sequence_seq" TO hmi_app;
GRANT USAGE, SELECT ON SEQUENCE public."auth_audit_audit_id_seq" TO hmi_app;
GRANT USAGE, SELECT ON SEQUENCE public."command_request_audit_id_seq" TO hmi_app;
GRANT USAGE, SELECT ON SEQUENCE public."event_apply_errors_error_id_seq" TO hmi_app;
GRANT USAGE, SELECT ON SEQUENCE public."ingest_conflicts_conflict_id_seq" TO hmi_app;
GRANT USAGE, SELECT ON SEQUENCE public."mes_management_audit_id_seq" TO hmi_app;
GRANT USAGE, SELECT ON SEQUENCE public."run_summary_conflicts_id_seq" TO hmi_app;
GRANT EXECUTE ON FUNCTION public."alarm_append_only"() TO hmi_app;
GRANT EXECUTE ON FUNCTION public."immutable_work_order_cancellation"() TO hmi_app;
SET search_path = public;
SET row_security = on;
RESET ROLE;
DO $$ BEGIN
 IF (SELECT count(*) FROM public.alembic_version) <> 1
   OR (SELECT version_num FROM public.alembic_version) <> '0014_mixed_alarm_runtime'
   OR (SELECT count(*) FROM pg_tables WHERE schemaname='public') <> 42
   OR EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public' AND tableowner<>'hmi_migrator')
   OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname='public' AND r.rolname='hmi_app')
   OR pg_has_role('hmi_app','hmi_migrator','MEMBER')
   OR has_schema_privilege('hmi_app','public','CREATE')
   OR has_database_privilege('hmi_app','hmi_mes_demo','TEMP')
   OR has_table_privilege('hmi_app','public.alembic_version','INSERT,UPDATE,DELETE,TRUNCATE')
   OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN ('hmi_app','hmi_migrator')
       AND (rolcanlogin OR rolsuper OR rolcreatedb OR rolcreaterole
         OR rolreplication OR rolbypassrls)) THEN
  RAISE EXCEPTION 'Unexpected schema, owner, role or privilege state';
 END IF;
END $$;
COMMIT;
SELECT (SELECT version_num FROM public.alembic_version) AS schema_revision,
 (SELECT count(*) FROM public.sites) AS sites,
 (SELECT count(*) FROM public.lines) AS lines,
 (SELECT count(*) FROM public.assets) AS assets,
 (SELECT count(*) FROM public.tag_definitions) AS tags,
 (SELECT count(*) FROM public.roles) AS roles;
